#!/usr/bin/env python3
"""Generates Sources/SkinKit/DefaultFontArt.swift from Tools/font_art.py.

    python3 Tools/generate_font_art.py

Keeps the pixel art in one place: edit font_art.py, run this, commit both.
"""

import os
import sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import font_art  # noqa: E402

OUTPUT = os.path.join(
    os.path.dirname(os.path.dirname(os.path.abspath(__file__))),
    "Sources", "SkinKit", "DefaultFontArt.swift",
)

HEADER = '''import Foundation

// Generated by Tools/generate_font_art.py from Tools/font_art.py.
// Edit the art there and regenerate; do not hand-edit this file.

/// The 5x6 pixel font used by the built-in skin.
///
/// One entry per glyph: six rows of up to five columns, where `#` is on. Ink
/// stays inside the first four columns so the fifth acts as a gutter — the
/// renderer advances a fixed 5px per character with no kerning, so a glyph that
/// fills all five runs into its neighbour. `M` and `W` are the deliberate
/// exceptions, being unreadable in four columns.
///
/// Classic skins bring their own `text.bmp` and never touch this; it exists so
/// the app has a complete, working look with no skin files installed.
enum DefaultFontArt {

    static let glyphs: [Character: [String]] = [
%s
    ]
}
'''


def swift_character(char):
    if char == '"':
        return '"\\""'
    if char == "\\":
        return '"\\\\"'
    if ord(char) > 127:
        return '"\\u{%04X}"' % ord(char)
    return '"%s"' % char


def main():
    problems = font_art.validate()
    if problems:
        for problem in problems:
            print("PROBLEM:", problem, file=sys.stderr)
        return 1

    order = sorted(font_art.GLYPHS, key=lambda c: (ord(c) > 127, ord(c)))
    lines = []
    for char in order:
        art = ", ".join('"%s"' % row for row in font_art.GLYPHS[char])
        lines.append("        %s: [%s]," % (swift_character(char), art))

    with open(OUTPUT, "w") as handle:
        handle.write(HEADER % "\n".join(lines))
    print(f"wrote {OUTPUT} ({len(order)} glyphs)")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
